import{_ as s,a0 as r,w as p,s as u,ao as n,I as a,x as o,a1 as d,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const q=JSON.parse('{"title":"Auditd - Linux 服務器安全審計工具 | LCTT x X-CMD","titleTemplate":false,"description":"Auditd - Linux 服務器安全審計工具 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Auditd - Linux 服務器安全審計工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Auditd - Linux 服務器安全審計工具 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150104 Auditd--Tool for Security Auditing on Linux Server","title":"Auditd - Linux 服務器安全審計工具","tag":"201502","desc":""},"relativePath":"201502/20150104 Auditd--Tool for Security Auditing on Linux Server.md","filePath":"[post].md"}'),l={name:"201502/20150104 Auditd--Tool for Security Auditing on Linux Server.md"};function g(c,t,m,h,b,x){const i=r("Link");return p(),u("div",null,[t[18]||(t[18]=n('<h1 id="auditd-linux-服務器安全審計工具" tabindex="-1">Auditd - Linux 服務器安全審計工具 <a class="header-anchor" href="#auditd-linux-服務器安全審計工具" aria-label="Permalink to “Auditd - Linux 服務器安全審計工具”">​</a></h1><p>首先，Linux中國祝賀讀者 <strong>2015羊年春節快樂，萬事如意！</strong> 。下面開始這個新年版審計工具的介紹。</p><p>安全防護是首先要考慮的問題。為了避免別人盜取我們的數據，我們需要時刻關注它。安全防護包括很多東西，審計是其中之一。</p><p>我們知道Linux系統上有一個叫 <strong>auditd</strong> 的審計工具。這個工具在大多數Linux操作系統中是默認安裝的。那麼auditd 是什麼？如何使用呢？下面我們開始介紹。</p><h3 id="什麼是審計" tabindex="-1">什麼是審計？ <a class="header-anchor" href="#什麼是審計" aria-label="Permalink to “什麼是審計？”">​</a></h3><p>auditd（或 auditd 守護進程）是Linux審計系統中用户空間的一個組件，其負責將審計記錄寫入磁盤。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/what_is_auditd.png" alt=""></p><h3 id="安裝-auditd" tabindex="-1">安裝 auditd <a class="header-anchor" href="#安裝-auditd" aria-label="Permalink to “安裝 auditd”">​</a></h3>',8)),a("p",null,[t[1]||(t[1]=o("Ubuntu系統中，我們可以使用 ",-1)),d(i,{href:"http://linoxide.com/tools/wajig-package-management-debian/"},{default:e(()=>[...t[0]||(t[0]=[o("wajig",-1)])]),_:1}),t[2]||(t[2]=o(" 工具或者 ",-1)),t[3]||(t[3]=a("strong",null,"apt-get 工具",-1)),t[4]||(t[4]=o(" 安裝auditd。",-1))]),t[19]||(t[19]=n(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/install_auditd.png" alt=""></p><p>按照下面的説明安裝auditd，安裝完畢後將自動安裝以下auditd和相關的工具：</p><ul><li><strong>auditctl :</strong> 即時控制審計守護進程的行為的工具，比如如添加規則等等。</li><li><strong>/etc/audit/audit.rules :</strong> 記錄審計規則的文件。</li><li><strong>aureport :</strong> 查看和生成審計報告的工具。</li><li><strong>ausearch :</strong> 查找審計事件的工具</li><li><strong>auditspd :</strong> 轉發事件通知給其他應用程序，而不是寫入到審計日誌文件中。</li><li><strong>autrace :</strong> 一個用於跟蹤進程的命令。</li><li><strong>/etc/audit/auditd.conf :</strong> auditd工具的配置文件。</li></ul><p>首次安裝 <strong>auditd</strong> 後, 審計規則是空的。</p><p>可以使用以下命令查看：</p><pre><code>$ sudo auditctl -l
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/auditctl_no_rules.png" alt=""></p><p>以下我們介紹如何給auditd添加審計規則。</p><h3 id="如何使用auditd" tabindex="-1">如何使用auditd <a class="header-anchor" href="#如何使用auditd" aria-label="Permalink to “如何使用auditd”">​</a></h3><h4 id="audit-文件和目錄訪問審計" tabindex="-1">Audit 文件和目錄訪問審計 <a class="header-anchor" href="#audit-文件和目錄訪問審計" aria-label="Permalink to “Audit 文件和目錄訪問審計”">​</a></h4><p>我們使用審計工具的一個基本的需求是監控文件和目錄的更改。使用auditd工具，我們可通過如下命令來配置(注意，以下命令需要root權限)。</p><p><strong>文件審計</strong></p><pre><code>$ sudo auditctl -w /etc/passwd -p rwxa
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/auditctl_w_etc_passwd.png" alt=""></p><p><strong>選項 :</strong></p><ul><li><strong>-w path :</strong> 指定要監控的路徑，上面的命令指定了監控的文件路徑 /etc/passwd</li><li><strong>-p :</strong> 指定觸發審計的文件/目錄的訪問權限</li><li><strong>rwxa ：</strong> 指定的觸發條件，r 讀取權限，w 寫入權限，x 執行權限，a 屬性（attr）</li></ul><h4 id="目錄審計" tabindex="-1">目錄審計 <a class="header-anchor" href="#目錄審計" aria-label="Permalink to “目錄審計”">​</a></h4><p>使用類似的命令來對目錄進行審計，如下：</p><pre><code>$ sudo auditctl -w /production/
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/auditctl_w_production.png" alt=""></p><p>以上命令將監控對 <strong>/production 目錄</strong> 的所有訪問。</p><p>現在，運行 <strong>auditctl -l</strong> 命令即可查看所有已配置的規則。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/auditctl_rules.png" alt=""></p><p>下面開始介紹審計日誌。</p><h3 id="查看審計日誌" tabindex="-1">查看審計日誌 <a class="header-anchor" href="#查看審計日誌" aria-label="Permalink to “查看審計日誌”">​</a></h3><p>添加規則後，我們可以查看 auditd 的日誌。使用 <strong>ausearch</strong> 工具可以查看auditd日誌。</p><p>我們已經添加規則監控 /etc/passwd 文件。現在可以使用 <strong>ausearch</strong> 工具的以下命令來查看審計日誌了。</p><pre><code>$ sudo ausearch -f /etc/passwd
</code></pre><ul><li><strong>-f</strong> 設定ausearch 調出 /etc/passwd文件的審計內容</li></ul><p>下面是輸出 ：</p><blockquote><p><strong>time</strong>-&gt;Mon Dec 22 09:39:16 2014</p></blockquote><blockquote><p>type=PATH msg=audit(1419215956.471:194): item=0 <strong>name=&quot;/etc/passwd&quot;</strong> inode=142512 dev=08:01 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=NORMAL</p></blockquote><blockquote><p>type=CWD msg=audit(1419215956.471:194): <strong>cwd=&quot;/home/pungki&quot;</strong></p></blockquote><blockquote><p>type=SYSCALL msg=audit(1419215956.471:194): arch=40000003 <strong>syscall=5</strong> success=yes exit=3 a0=b779694b a1=80000 a2=1b6 a3=b8776aa8 items=1 ppid=2090 pid=2231 <strong>auid=4294967295 uid=1000 gid=1000</strong> euid=0 suid=0 fsuid=0 egid=1000 sgid=1000 fsgid=1000 tty=pts0 ses=4294967295 <strong>comm=&quot;sudo&quot; exe=&quot;/usr/bin/sudo&quot;</strong> key=(null)</p></blockquote><p>下面開始解讀輸出結果。</p><ul><li><strong>time :</strong> 審計時間。</li><li><strong>name :</strong> 審計對象</li><li><strong>cwd :</strong> 當前路徑</li><li><strong>syscall :</strong> 相關的系統調用</li><li><strong>auid :</strong> 審計用户ID</li><li><strong>uid 和 gid :</strong> 訪問文件的用户ID和用户組ID</li><li><strong>comm :</strong> 用户訪問文件的命令</li><li><strong>exe :</strong> 上面命令的可執行文件路徑</li></ul><p>以上審計日誌顯示文件未被改動。</p><p>以下我們將要添加一個用户，看看auditd如何記錄文件 /etc/passwd的改動的。</p><blockquote><p>**time-&gt;**Mon Dec 22 11:25:23 2014</p></blockquote><blockquote><p>type=PATH msg=audit(1419222323.628:510): item=1 <strong>name=&quot;/etc/passwd.lock&quot;</strong> inode=143992 dev=08:01 mode=0100600 ouid=0 ogid=0 rdev=00:00 nametype=DELETE</p></blockquote><blockquote><p>type=PATH msg=audit(1419222323.628:510): item=0 <strong>name=&quot;/etc/&quot;</strong> inode=131073 dev=08:01 mode=040755 ouid=0 ogid=0 rdev=00:00 nametype=PARENT</p></blockquote><blockquote><p>type=CWD msg=audit(1419222323.628:510): <strong>cwd=&quot;/root&quot;</strong></p></blockquote><blockquote><p>type=SYSCALL msg=audit(1419222323.628:510): arch=40000003 <strong>syscall=10</strong> success=yes exit=0 a0=bfc0ceec a1=0 a2=bfc0ceec a3=897764c items=2 ppid=2978 pid=2994 <strong>auid=4294967295 uid=0 gid=0</strong> euid=0 suid=0 fsuid=0 egid=0 sgid=0 fsgid=0 tty=pts0 ses=4294967295 <strong>comm=&quot;chfn&quot; exe=&quot;/usr/bin/chfn&quot;</strong> key=(null)</p></blockquote><p>我們可以看到，在指定的時間，<strong>/etc/passwd ** 被root用户(uid =0, gid=0)在/root目錄下修改。/etc/passwd 文件是使用</strong>/usr/bin/chfn** 訪問的。</p><p>鍵入 <strong>man chfn</strong> 可以查看有關chfn更多的信息。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/chfn.png" alt=""></p><p>下面我們看另外一個例子。</p><p>我們已經配置auditd去監控目錄 /production/ 了。這是個新目錄。所以我們用ausearch去查看日誌的時候會發現什麼都沒有。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/ausearch_production_empty.png" alt=""></p><p>下一步，使用root賬户的ls命令列出 /production/ 下的文件信息。再次使用ausearch後，將會顯示一些信息。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/ausearch_production_ls.png" alt=""></p><blockquote><p>**time-&gt;**Mon Dec 22 14:18:28 2014 type=PATH msg=audit(1419232708.344:527): item=0 <strong>name=&quot;/production/&quot;</strong> inode=797104 dev=08:01 mode=040755 ouid=0 ogid=0 rdev=00:00 nametype=NORMAL type=CWD msg=audit(1419232708.344:527): cwd=&quot;/root&quot; type=SYSCALL msg=audit(1419232708.344:527): arch=40000003 syscall=295 success=yes exit=3 a0=ffffff9c a1=95761e8 a2=98800 a3=0 items=1 ppid=3033 pid=3444 <strong>auid=4294967295 uid=0 gid=0</strong> euid=0 suid=0 fsuid=0 egid=0 sgid=0 fsgid=0 tty=pts0 ses=4294967295 <strong>comm=&quot;ls&quot; exe=&quot;/bin/ls&quot;</strong> key=(null)</p></blockquote><p>和上一個一樣，可以得出root賬户使用ls命令訪問了/production/目錄，ls命令的文件目錄是 /bin/ls</p><h3 id="查看審計報告" tabindex="-1">查看審計報告 <a class="header-anchor" href="#查看審計報告" aria-label="Permalink to “查看審計報告”">​</a></h3><p>一旦定義審計規則後，它會自動運行。過一段時間後，我們可以看看auditd是如何幫我們跟蹤審計的。</p><p>Auditd提供了另一個工具叫 <strong>aureport</strong> 。從名字上可以猜到， <strong>aureport</strong> 是使用系統審計日誌生成簡要報告的工具。</p><p>我們已經配置auditd去跟蹤/etc/passwd文件。auditd參數設置後一段時間後，audit.log 文件就創建出來了。</p><p>生成審計報告，我們可以使用aureport工具。不帶參數運行的話，可以生成審計活動的概述。</p><pre><code>$ sudo aureport
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/aureport_2.png" alt=""></p><p>如上，報告包含了大多數重要區域的信息。</p><p>上圖可以看出有 <strong>3 次授權失敗</strong>。 使用aureport，我們可以深入查看這些信息。</p><p>使用以下命令查看授權失敗的詳細信息：</p><pre><code>$ sudo aureport -au
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/aureport_authentication.png" alt=""></p><p>從上圖可以看出，由兩個用户在特定的時間授權失敗。</p><p>如果我們想看所有賬户修改相關的事件，可以使用-m參數。</p><pre><code>$ sudo aureport -m
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/aureport_m.png" alt=""></p><h3 id="auditd-配置文件" tabindex="-1">Auditd 配置文件 <a class="header-anchor" href="#auditd-配置文件" aria-label="Permalink to “Auditd 配置文件”">​</a></h3><p>我們已經添加如下規則：</p><ul><li>$ sudo auditctl -w /etc/passwd -p rwxa</li><li>$ sudo auditctl -w /production/</li></ul><p>現在，如果確信這些規則可以正常工作，我們可以將其添加到<strong>/etc/audit/audit.rules</strong>中使得規則永久有效。以下介紹如何將他們添加到/etc/audit/audit.rules中去。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/audit_rules_file.png" alt=""></p><p><strong>最後，別忘了重啓auditd守護程序</strong></p><pre><code># /etc/init.d/auditd restart
</code></pre><p>或</p><pre><code># service auditd restart
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/audit_restart.png" alt=""></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Auditd是Linux上的一個審計工具。你可以閲讀auidtd文檔獲取更多使用auditd和工具的細節。例如，輸入 <strong>man auditd</strong> 去看auditd的詳細説明，或者鍵入 <strong>man ausearch</strong> 去看有關 ausearch 工具的詳細説明。</p><p><strong>請謹慎創建規則</strong>。太多規則會使得日誌文件急劇增大！</p><hr>`,83)),a("p",null,[t[6]||(t[6]=o("via: ",-1)),d(i,{href:"http://linoxide.com/how-tos/auditd-tool-security-auditing/"},{default:e(()=>[...t[5]||(t[5]=[o("http://linoxide.com/how-tos/auditd-tool-security-auditing/",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=o("作者：",-1)),d(i,{href:"http://linoxide.com/author/pungki/"},{default:e(()=>[...t[7]||(t[7]=[o("Pungki Arianto",-1)])]),_:1}),t[11]||(t[11]=o(" 譯者：",-1)),d(i,{href:"https://github.com/shipsw"},{default:e(()=>[...t[8]||(t[8]=[o("shipsw",-1)])]),_:1}),t[12]||(t[12]=o(" 校對：",-1)),d(i,{href:"https://github.com/wxy"},{default:e(()=>[...t[9]||(t[9]=[o("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=o("本文由 ",-1)),d(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[13]||(t[13]=[o("LCTT",-1)])]),_:1}),t[16]||(t[16]=o(" 原創翻譯，",-1)),d(i,{href:"http://linux.cn/"},{default:e(()=>[...t[14]||(t[14]=[o("Linux中國",-1)])]),_:1}),t[17]||(t[17]=o(" 榮譽推出",-1))])])}const k=s(l,[["render",g]]);export{q as __pageData,k as default};
